#include "IslandSimulator/IslandTerrain.hpp"
#include "IslandSimulator/OctopusGroup.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
int main(){const auto require=[](bool v,const char* m){if(!v)throw std::runtime_error(m);};island::IslandTerrain terrain;island::OctopusGroup group(terrain),repeat(terrain),invalid(terrain);require(group.Octopuses().size()==island::OctopusGroup::Count&&group.Dens().size()==island::OctopusGroup::Count,"octopus inventory changed");std::vector<island::OctopusState> start(group.Octopuses().begin(),group.Octopuses().end());for(std::size_t i=0;i<start.size();++i){const auto s=terrain.Sample(start[i].x,start[i].z);require(start[i].x==repeat.Octopuses()[i].x&&start[i].behavior==repeat.Octopuses()[i].behavior,"octopus initialization is not deterministic");require(s.surface==island::TerrainSurface::ShallowSeabed&&s.height<=-.9f,"octopus den escaped rocky shallows");}for(int f=0;f<7200;++f){group.Update(1.f/60,0,5,0);repeat.Update(1.f/60,0,5,0);}float travel=0;for(std::size_t i=0;i<start.size();++i){const auto& o=group.Octopuses()[i];const auto& same=repeat.Octopuses()[i];require(o.x==same.x&&o.y==same.y&&o.z==same.z&&o.armWave==same.armWave,"octopus simulation is not deterministic");require(std::hypot(o.x-group.Dens()[i].x,o.z-group.Dens()[i].z)<=group.Dens()[i].radius+.02f,"octopus escaped den range");require(o.y>terrain.Height(o.x,o.z)+.04f&&o.y<-.15f,"octopus clipped seabed or surface");travel+=std::hypot(o.x-start[i].x,o.z-start[i].z);}require(travel>.25f,"octopuses did not move");require(group.FullSimulationCount()+group.ReducedSimulationCount()+group.DormantSimulationCount()==static_cast<int>(island::OctopusGroup::Count),"octopus activation accounting changed");invalid.Update(NAN,NAN,NAN,NAN);require(invalid.DormantSimulationCount()==static_cast<int>(island::OctopusGroup::Count),"invalid update did not fail dormant");std::cout<<"Octopuses: four deterministic reef-den agents remain bounded\n";}
